 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Each nested rectangular design is a 4-connected non-background component.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))

            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            layers = []
            top, bottom, left, right = r0, r1, c0, c1
            while top <= bottom and left <= right:
                border = set()
                for x in range(left, right + 1):
                    border.add((top, x))
                    border.add((bottom, x))
                for y in range(top, bottom + 1):
                    border.add((y, left))
                    border.add((y, right))
                colors = {grid[y][x] for y, x in border}
                if len(colors) != 1 or 0 in colors:
                    break
                color = next(iter(colors))
                layers.append((color, border))
                top += 1
                bottom -= 1
                left += 1
                right -= 1

            # Reverse the colors of successive rectangular bands, retaining each band's shape.
            if len(layers) > 1:
                reversed_colors = [color for color, _ in layers[::-1]]
                for (old_color, coords), new_color in zip(layers, reversed_colors):
                    for y, x in coords:
                        out[y][x] = new_color
    return out


if __name__ == '__main__':
    pass
